<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Rendering\Domain;

enum TemplateOutputFormat: string
{
    /**
     * Standard HTML output. CSS assets are listed in the result but kept as external references;
     * callers are responsible for linking them in the page.
     */
    case HTML = 'html';

    /**
     * Self-contained HTML. Every CSS asset in the request is injected as a <style> block
     * inside the document <head>, making the document suitable for email clients or
     * sandboxed frames that cannot load external stylesheets.
     */
    case HTML_EMBEDDED = 'html_embedded';

    /**
     * Plain Markdown text. Reserved for future use.
     */
    case MARKDOWN = 'markdown';

    /**
     * PDF binary output. Reserved for future use.
     */
    case PDF = 'pdf';
}
